const lessons=[
{focus:"Foundation: clear workplace sentences",level:"Foundation",minutes:15,speakTitle:"Introduce yourself professionally",speakPrompt:"Imagine a new lawyer or coworker asks: “Tell me a little about what you do.” Answer in 20–30 seconds.",question:"Tell me a little about what you do.",instruction:"Use: role → main work → one strength. Keep it simple.",tip:"Speak 10% slower than normal. Finish each sentence before starting the next one.",examples:[["Simple","I work at a law firm and support the legal team.","Try this"],["Clear","I mainly work on Accident Benefits files and help move files toward settlement.","Use this"],["More natural","I mainly handle Accident Benefits work, including client updates and insurer correspondence.","Use this"],["Confident","I manage a large caseload and make sure deadlines and next steps are kept on track.","Use this"],["Strong","I support the legal team from file opening through settlement, while keeping communication clear with clients and other parties.","Use this"]],scenario:["Internal","Easy","A coworker asks what you are currently working on.","Give a short update without giving unnecessary detail."],choices:["“I’m doing some files.”","“I’m currently working on several Accident Benefits files. I’m updating the files and following up on outstanding items.”","“It’s complicated.”"],model:"“I’m currently working on several Accident Benefits files. I’ve completed the urgent follow-ups and I’m now working through the outstanding documents.”",phrases:["I’m currently working on…","The main priority is…","I’ve completed…","I’m waiting for…","The next step is…"],email:["Write a clear status update","Write a 3–4 sentence update to a supervisor about a file.","Good afternoon,<br><br>I wanted to provide a quick update on the file. I have completed the outstanding follow-ups and am currently waiting for the remaining documents. Once received, I’ll review them and confirm the next steps.<br><br>Thank you."],edits:[["“I just wanted to ask if maybe…”","“Could you please confirm…”"],["“Please advise ASAP.”","“Please let me know when you have a chance.”"],["“I am following up again because…”","“I’m following up on the email below regarding…”"],["“Let me know.”","“Please let me know if you have any questions.”"],["“Sorry for bothering you.”","“Thank you for your time.”"]],read:["A clear file update","A strong legal workplace update is short and structured. Start with what has been completed. Then identify what is outstanding. Finally, explain the next step. This structure helps lawyers, clients, adjusters and coworkers understand the status quickly. Clear communication is not about using complicated words; it is about making the important information easy to find."],vocab:[["outstanding","not yet completed or received"],["follow-up","a communication sent to check progress"],["confirm","to make sure information is correct"],["priority","the item that should be handled first"],["proceed","to continue or move forward"]],typing:"I have completed the initial review and will follow up on the outstanding documents tomorrow."},
{focus:"Asking for clarification",level:"Foundation",minutes:16,speakTitle:"Ask a professional question",speakPrompt:"You receive an instruction but one part is unclear. Ask a clear question instead of staying silent.",question:"Could you clarify which document you would like me to prepare first?",instruction:"State what you understand, then ask one specific question.",tip:"Confident people ask precise questions. Replace “Sorry, I don’t understand” with a focused question.",examples:[["Basic","Could you clarify this for me?","Try this"],["Specific","Could you clarify which document you would like first?","Use this"],["Natural","Just to confirm, which item would you like me to prioritize?","Use this"],["Professional","I want to make sure I’m handling this correctly. Could you clarify the next step?","Use this"],["Strong","Just to confirm my understanding, should I complete the draft first and then send it to you for review?","Use this"]],scenario:["Internal","Easy","A supervisor gives you two instructions at once and you are unsure which is urgent.","Clarify the priority without sounding unsure of yourself."],choices:["“Which one?”","“I can work on both. Since they are both time-sensitive, which would you like me to prioritize first?”","“I can’t do this.”"],model:"“I can work on both. Since they are both time-sensitive, could you please let me know which one you would like me to prioritize first?”",phrases:["Just to confirm…","Could you clarify…","My understanding is…","Would you like me to…","Which would you prefer?"] ,email:["Ask for clarification","Write a short message asking which of two tasks should be completed first.","Hi Jonathan,<br><br>I can work on both items. Since they are both time-sensitive, could you please let me know which one you would like me to prioritize first?<br><br>Thank you."],edits:[["“What do you mean?”","“Could you clarify what you mean by…?”"],["“Which one should I do?”","“Which would you like me to prioritize?”"],["“I don’t get it.”","“I want to make sure I understand correctly.”"],["“So what now?”","“Could you please confirm the next step?”"],["“Is this right?”","“Just to confirm, is my understanding correct?”"]],read:["The confident question","In a law office, asking a question early can prevent a larger mistake later. A strong question is specific and shows that you have already considered the task. Instead of saying that you do not understand anything, identify the exact point that needs clarification. This makes the conversation faster and more professional."],vocab:[["clarify","to make something easier to understand"],["understanding","what you believe has been explained"],["prioritize","to decide what should be done first"],["specific","clear and exact rather than general"],["appropriate","suitable for the situation"]],typing:"Just to confirm, would you like me to complete the draft first and send it to you for review?"},
{focus:"Professional small talk",level:"Foundation",minutes:16,speakTitle:"Keep a conversation going",speakPrompt:"A coworker asks, “How was your weekend?” Answer naturally and ask one follow-up question.",question:"How was your weekend?",instruction:"Answer + one detail + a follow-up question.",tip:"You do not need an impressive answer. A simple answer plus a question keeps the conversation moving.",examples:[["Short","It was good, thanks. How was yours?","Try this"],["Natural","It was pretty good. I got some errands done and relaxed a bit. How about you?","Use this"],["Warm","It was nice and quiet. I finally had time to catch up on a few things. Did you do anything fun?","Use this"],["Work-friendly","It was good. I spent some time outside, which was nice. How was your weekend?","Use this"],["Confident","It was great, actually. I had a pretty relaxed weekend and got some things done. How about you?","Use this"]],scenario:["Internal","Easy","You are waiting for a meeting to start and a coworker makes small talk.","Respond naturally rather than giving a one-word answer."],choices:["“Good.”","“It was good, thanks. I had a pretty relaxed weekend. How was yours?”","“Why do you ask?”"],model:"“It was good, thanks. I had a pretty relaxed weekend and got some errands done. How about you?”",phrases:["How about you?","That sounds nice.","How did that go?","That must have been…","What about you?"] ,email:["Friendly Teams message","Write a brief professional message to a coworker before asking them a work question.","Hi Sarah, hope your week is going well. When you have a quick minute, could I ask you about something on the file?"],edits:[["“Hey, I need something.”","“Hi Sarah, when you have a moment, could I ask you about…”"],["“Are you free?”","“Do you have a quick minute when you’re free?”"],["“Thanks.”","“Thanks, I really appreciate it.”"],["“No problem.”","“Absolutely, happy to help.”"],["“What’s up?”","“How are things going on your end?”"]],read:["Small talk is a professional skill","Small talk is not wasted conversation. It helps coworkers build rapport and makes future requests feel more natural. You do not need to talk for long. One answer, one detail and one follow-up question is enough. The goal is to sound interested, not rehearsed."],vocab:[["rapport","a comfortable and positive relationship"],["natural","comfortable and not forced"],["brief","short in duration or length"],["engage","to take part in a conversation"],["appropriate","suitable or professional"]],typing:"It was good, thanks. I had a relaxing weekend. How was yours?"},
{focus:"Prioritizing tasks",level:"Foundation",minutes:17,speakTitle:"Handle competing deadlines",speakPrompt:"Two urgent files arrive at the same time. Explain that you can handle both, but need the priority confirmed.",question:"I need these two items today. Which one can you prioritize first?",instruction:"Stay calm. Do not complain about the workload; clarify the order.",tip:"Replace stress language with planning language: “I can handle both. Which would you like first?”",examples:[["Simple","Which one should I do first?","Try this"],["Clear","I can work on both. Which one would you like me to prioritize?","Use this"],["Polite","I can handle both items. Since they are both time-sensitive, which should I prioritize first?","Use this"],["Confident","I can complete both. To manage the deadlines properly, could you confirm which is the higher priority?","Use this"],["Strong","I can work on both within the available time. Since they have competing deadlines, could you confirm which one you would like me to prioritize first?","Use this"]],scenario:["Internal","Medium","You have an OCF request, a LAT deadline and an urgent client call on the same afternoon.","Explain your priorities and ask for direction where needed."],choices:["“I’m too busy.”","“I have three time-sensitive items. I can handle them, but I’d like to confirm which one should take priority.”","“I can’t finish anything.”"],model:"“I have three time-sensitive items this afternoon. I can work through them, but I’d like to confirm which deadline you would like me to prioritize first.”",phrases:["I have a few time-sensitive items.","The main priority is…","To manage the deadlines…","Could you confirm…","I can complete this by…"],email:["Prioritization message","Write to a supervisor when three tasks have competing deadlines.","Good afternoon,<br><br>I have three time-sensitive items to complete today. I can work through all three, but could you please confirm which deadline you would like me to prioritize first?<br><br>Thank you."],edits:[["“I’m swamped.”","“I have several time-sensitive items.”"],["“I can’t do all this.”","“I can complete these, but I need to confirm the priority.”"],["“Which one is more important?”","“Which would you like me to prioritize first?”"],["“I’ll try.”","“I’ll aim to have this completed by…”"],["“It will be late.”","“The timeline may need to be adjusted.”"]],read:["Priorities and deadlines","Legal work often involves several deadlines at once: client requests, insurer correspondence, productions, LAT steps, medical records and settlement preparation. Good communication makes priorities visible. When you need direction, give the facts first, then ask one focused question."],vocab:[["time-sensitive","requiring attention within a limited time"],["deadline","the date or time by which something must be completed"],["priority","the task handled before another task"],["timeline","the expected schedule for completing work"],["adjust","to change something slightly to fit new circumstances"]],typing:"I can complete both items, but could you please confirm which one you would like me to prioritize first?"},
{focus:"Client calls: calm and clear",level:"Foundation",minutes:18,speakTitle:"Answer a client who wants an update",speakPrompt:"A client calls and says, “I’ve been waiting. What is happening with my file?” Give a calm response without promising an outcome.",question:"I’ve been waiting. What is happening with my file?",instruction:"Acknowledge → current status → next step. Never guess a legal outcome.",tip:"Your voice can sound confident even when you do not have every answer. Use: “Let me check that for you.”",examples:[["Acknowledge","I understand. Let me check the current status for you.","Try this"],["Status","I understand the wait can be frustrating. Let me review the file and confirm where things stand.","Use this"],["Next step","I’ll review the latest information and let you know what the next step is.","Use this"],["Boundary","I don’t want to give you incorrect information, so let me confirm that with the lawyer first.","Use this"],["Strong","I understand your concern. Let me review the most recent file information and confirm the current status and next step for you.","Use this"]],scenario:["Client call","Medium","A client is frustrated because they have not heard an update on their Accident Benefits file.","De-escalate, clarify what you can confirm, and avoid making legal promises."],choices:["“You just have to wait.”","“I understand your concern. Let me review the latest information and confirm the current status for you.”","“The insurer is definitely going to pay.”"],model:"“I understand your concern. I don’t want to give you incomplete information, so let me review the latest notes and confirm the current status with you.”",phrases:["I understand your concern.","Let me check that for you.","Let me confirm the current status.","I don’t want to give you incorrect information.","I’ll make sure the appropriate person follows up."] ,email:["Client follow-up","Write a client-friendly email after a call where you promised to check the file.","Good afternoon,<br><br>Further to our call, I am reviewing the current status of your file and will confirm the next steps once I have the necessary information. Thank you for your patience.<br><br>Kind regards,"],edits:[["“You need to wait.”","“I understand the wait can be frustrating.”"],["“I don’t know.”","“Let me confirm that information for you.”"],["“The lawyer will call.”","“I’ll make sure your request is brought to the lawyer’s attention.”"],["“We’re working on it.”","“We are reviewing the outstanding items and will update you on the next step.”"],["“You’re covered.”","“I’ll confirm the applicable benefits with the lawyer.”"]],read:["Client communication","Clients usually want three things: to know that they were heard, to understand what is happening now, and to know what happens next. In legal work, avoid guessing or promising results. A calm explanation and a clear follow-up can build trust even when the answer is not yet available."],vocab:[["de-escalate","to reduce tension in a difficult interaction"],["concern","a worry or issue someone wants addressed"],["confirm","to verify information"],["outcome","the final result"],["follow-up","a later action or communication"],],typing:"I understand your concern. Let me review the latest information and confirm the current status for you."},
{focus:"Counsel / adjuster calls",level:"Developing",minutes:19,speakTitle:"Handle a professional call",speakPrompt:"Opposing counsel or an adjuster asks whether there is an appetite to resolve the file. Respond professionally and keep the conversation moving.",question:"Is there any appetite on your end to resolve this file?",instruction:"Do not over-explain. State the current position and identify the next step.",tip:"Use a neutral tone. “At this time…” sounds more professional than “We don’t want to…”",examples:[["Neutral","At this time, I’ll need to confirm our position before responding.","Try this"],["Direct","At this time, counsel would like to know whether there is an appetite to close the file.","Use this"],["Settlement","If there is an interest in resolving the file, please let us know your availability for a settlement call.","Use this"],["Follow-up","I’ll confirm counsel’s position and follow up once I have instructions.","Use this"],["Strong","At this time, counsel would like to know whether there is an appetite on your end to resolve the file. If so, please let us know your availability for a settlement call.","Use this"]],scenario:["Counsel / adjuster","Medium","You are following up on a file and counsel wants to know whether the other side is open to settlement.","Use precise, neutral language and move toward a call if appropriate."],choices:["“Do you want to settle or not?”","“At this time, counsel would like to know whether there is an appetite on your end to resolve the file.”","“We really need this settled.”"],model:"“At this time, counsel would like to know whether there is an appetite on your end to resolve the file. If so, please let us know your availability for a settlement call.”",phrases:["At this time…","Counsel would like to know…","There is an appetite to…","Please advise…","Please indicate your availability…"],email:["Settlement follow-up","Draft a concise email asking whether there is an appetite to resolve a file and requesting availability.","Good afternoon,<br><br>At this time, counsel would like to know whether there is an appetite on your end to resolve this file. If so, please advise and indicate your availability for a settlement call this or next week.<br><br>Regards,"],edits:[["“Do you want to settle?”","“Is there an appetite on your end to resolve this file?”"],["“Call me when you can.”","“Please indicate your availability for a settlement call.”"],["“We want to settle.”","“Counsel would like to explore whether the matter can be resolved.”"],["“Send us your answer.”","“Please advise at your earliest convenience.”"],["“This is urgent.”","“Given the upcoming timeline, a prompt response would be appreciated.”"]],read:["Professional legal communication","Correspondence with counsel, adjusters and representatives should be neutral, precise and easy to act on. Avoid emotional language. State the purpose of the email, the requested action and any relevant timeframe. Strong legal writing often sounds simple because unnecessary words have been removed."],vocab:[["appetite","willingness or interest in pursuing an option"],["resolve","to settle or bring an issue to an end"],["indicate","to state or show something clearly"],["availability","the times when someone is free"],["position","a party’s stated view or stance"],],typing:"At this time, counsel would like to know whether there is an appetite on your end to resolve this file."},
{focus:"Proofreading: legal correspondence",level:"Developing",minutes:20,speakTitle:"Read your email before sending",speakPrompt:"Practice saying your message out loud before sending it. Focus on the date, requested action and tone.",question:"How would you check an important legal email before sending it?",instruction:"Explain your proofreading routine in 20–30 seconds.",tip:"Use a three-check routine: facts → action → tone.",examples:[["Facts","I check names, dates, file references and amounts.","Try this"],["Action","I make sure the recipient can see exactly what I’m asking them to do.","Use this"],["Tone","I remove emotional or unnecessary wording and keep the tone professional.","Use this"],["Complete","I check the facts, the requested action and the tone before I send it.","Use this"],["Strong","Before sending, I check names, dates, deadlines and file references, confirm that the requested action is clear, and then read the email once for tone and grammar.","Use this"]],scenario:["Internal","Medium","You are about to serve a LAT Case Conference Summary and Declaration of Representative.","Explain what you would check before sending."],choices:["“I just read it quickly.”","“I would check the names, dates, deadline, attachments, service wording and whether the requested action is clear.”","“I only check spelling.”"],model:"“Before sending, I’d check the parties’ names, dates, deadline, attachments, service language and whether the requested action is clear.”",phrases:["For your review…","Please find attached…","Pursuant to…","Further to the email below…","Please confirm receipt."] ,email:["Proofread a service email","Write a concise service email for a LAT filing.","Good afternoon,<br><br>Please find attached the Applicant’s LAT Case Conference Summary, dated September 9, 2026, together with the Declaration of Representative, which is hereby served upon you pursuant to the LAT Rules.<br><br>Regards,"],edits:[["“Please find attached the document which is attached.”","“Please find attached the document.”"],["“Please see attached herewith.”","“Please see the attached document.”"],["“I am just following up to the email below.”","“I am following up on the email below.”"],["“Kindly please advise.”","“Please advise.”"],["“Attached is the same.”","“Please find the requested document attached.”"]],read:["The proofreading pause","Before sending a legal email, pause for ten seconds. Check the recipient, attachment, dates, file reference, limitation or hearing date, and requested action. Then read the message once as if you were the recipient. Ask: “Would I know exactly what I need to do after reading this?”"],vocab:[["pursuant","in accordance with or following"],["serve","formally deliver a legal document to another party"],["attachment","a file included with an email"],["reference","information used to identify a file or matter"],["receipt","the act of receiving something"],],typing:"Please find attached the Applicant’s LAT Case Conference Summary, together with the Declaration of Representative."},
{focus:"Explaining legal work in plain English",level:"Developing",minutes:21,speakTitle:"Explain a legal step simply",speakPrompt:"Explain a legal process to a client without using unnecessary legal jargon.",question:"What happens next with my file?",instruction:"Use plain English: what happens now → why → when they can expect an update.",tip:"If a client does not need a legal term, do not use it.",examples:[["Plain","The next step is for us to review the documents.","Try this"],["Clear","We’re waiting for the remaining records before we can move forward.","Use this"],["Client-friendly","Once we receive the records, the lawyer can review the information and decide on the next step.","Use this"],["Reassuring","There is nothing you need to do right now. We are waiting for the outstanding information and will update you once we have it.","Use this"],["Strong","The next step is to obtain the outstanding records. Once they are received, the lawyer will review them and advise on the appropriate next step.","Use this"]],scenario:["Client call","Medium","A client asks what an OCF form or LAT step means.","Explain the purpose in plain language and avoid giving legal advice beyond your role."],choices:["“It’s an OCF.”","“It is a form used to provide information for the benefits process. I can confirm the specific requirements with the lawyer.”","“You have to fill it because that’s the law.”"],model:"“It is a form used in the Accident Benefits process to provide information. I can explain what we need from you and confirm any legal questions with the lawyer.”",phrases:["In simple terms…","The next step is…","What this means is…","For your part…","I can confirm that with the lawyer."] ,email:["Client-friendly update","Write an easy-to-understand update explaining that outstanding medical information is needed.","Good afternoon,<br><br>We are currently waiting for the outstanding medical information needed to continue reviewing your file. Once we receive it, we will review the information and advise you of the next step.<br><br>Thank you."],edits:[["“Pursuant to the foregoing…”","“Based on the information above…”"],["“You are required to…”","“We need you to…”"],["“The aforementioned documents…”","“The documents listed above…”"],["“Notwithstanding the foregoing…”","“However…”"],["“Commence”","“Start”"]],read:["Plain English builds trust","Clients should not need a law degree to understand a basic update. Plain English does not mean less professional. It means the important message is easier to understand. Use legal terminology when it is necessary, but explain it when the client needs context."],vocab:[["jargon","specialized language that may be difficult for others to understand"],["plain English","clear language that is easy for a general reader to understand"],["require","to need something"],["advise","to give information or guidance"],["context","background information that helps explain something"],],typing:"The next step is to review the outstanding information and confirm what is required."},
{focus:"Difficult conversation: frustrated caller",level:"Developing",minutes:22,speakTitle:"De-escalate a frustrated caller",speakPrompt:"A caller says, “Nobody ever calls me back.” Respond without becoming defensive.",question:"Nobody ever calls me back. What is going on?",instruction:"Acknowledge the frustration → take a useful action → set a realistic expectation.",tip:"Do not match the caller’s emotion. Lower your pace and your volume.",examples:[["Acknowledge","I understand why you’re frustrated.","Try this"],["Action","Let me check the file and see what the current status is.","Use this"],["Expectation","I’ll confirm the information and make sure the request is brought to the right person.","Use this"],["Boundary","I don’t want to speculate, so let me check the notes first.","Use this"],["Strong","I understand why you’re frustrated. Let me review the latest file notes so I can give you accurate information rather than guess. I’ll confirm the appropriate next step.","Use this"]],scenario:["Client call","Hard","A client is angry about repeated delays and says they are thinking of making a complaint.","Stay calm, do not argue, and escalate appropriately."],choices:["“That’s not my fault.”","“I understand why you’re frustrated. Let me review the file and make sure your concern is brought to the lawyer’s attention.”","“There’s nothing I can do.”"],model:"“I understand why you’re frustrated. I don’t want to give you incomplete information. Let me review the file and make sure your concern is brought to the lawyer’s attention.”",phrases:["I understand why you’re frustrated.","Let me look into that.","I don’t want to speculate.","Let me confirm the information.","I’ll make sure this is brought to the appropriate person."],email:["Difficult client follow-up","Write a calm email after a difficult call.","Good afternoon,<br><br>Further to our conversation, I understand your concerns regarding the current status of the file. I am reviewing the information and will bring your concerns to the lawyer’s attention so that the appropriate next step can be confirmed.<br><br>Kind regards,"],edits:[["“Calm down.”","“I understand this is frustrating.”"],["“That’s not my responsibility.”","“I’ll make sure your concern is directed to the appropriate person.”"],["“You’re wrong.”","“Let me clarify that point.”"],["“You need to be patient.”","“Thank you for your patience while we confirm the information.”"],["“I already told you.”","“As noted earlier, the current position is…”"]],read:["De-escalation is a skill","When a person is upset, your first job is not to win the argument. It is to reduce friction and identify the next useful action. Avoid defensive phrases. Acknowledge the concern, state what you can do, and avoid promises you cannot control."],vocab:[["defensive","acting as though you need to protect yourself from criticism"],["friction","tension or difficulty between people"],["speculate","to guess without enough information"],["escalate","to bring an issue to a higher level of attention"],["appropriate","right or suitable for the situation"],],typing:"I understand your concern. Let me review the file so I can confirm the current status accurately."},
{focus:"Settlement and negotiation",level:"Advanced",minutes:24,speakTitle:"Move a settlement conversation forward",speakPrompt:"The other side has indicated they may be open to resolving the matter. Explain the next step.",question:"What would you suggest as the next step toward resolution?",instruction:"Be concise. Suggest a call, confirm availability or request a response.",tip:"Confident legal communication is often short: position → proposal → next step.",examples:[["Simple","I suggest we arrange a settlement call.","Try this"],["Professional","I suggest we arrange a settlement call to discuss the matter further.","Use this"],["Specific","If counsel is agreeable, please provide your availability for a settlement call this or next week.","Use this"],["Neutral","We would be happy to explore resolution by way of a settlement call.","Use this"],["Strong","If there is an appetite to resolve the matter, we would be happy to arrange a settlement call. Please indicate your availability this or next week.","Use this"]],scenario:["Counsel / adjuster","Hard","You need to follow up with opposing counsel about whether they have an appetite to close the file.","Use neutral language and ask for availability."],choices:["“Can we just settle this?”","“If there is an appetite to resolve the matter, please indicate your availability for a settlement call.”","“We need you to settle.”"],model:"“At this time, counsel would like to know whether there is an appetite on your end to resolve this file. If so, please advise and indicate your availability for a settlement call this or next week.”",phrases:["explore resolution","resolve the matter","settlement call","counsel’s position","indicate your availability"],email:["Settlement call","Draft the follow-up after counsel asks whether there is an appetite to close the file.","Good afternoon,<br><br>At this time, counsel would like to know whether there is an appetite on your end to close this file. If so, please advise and indicate your availability for a settlement call this or next week.<br><br>Regards,"],edits:[["“Close this ASAP.”","“Please advise whether there is an appetite to resolve the matter.”"],["“What dates work?”","“Please indicate your availability.”"],["“Let’s talk about settlement.”","“We would be happy to discuss resolution by way of a settlement call.”"],["“We’re waiting for you.”","“We look forward to hearing from you.”"],["“Send a date.”","“Please provide your availability.”"]],read:["Settlement communication","Settlement correspondence should make the desired action obvious. A short email can be more effective than a long explanation. State that counsel is interested in resolution, ask whether the other side is open to it, and request availability. Keep the tone neutral even when a file has been difficult."],vocab:[["resolution","a solution that brings a dispute to an end"],["negotiate","to discuss terms in order to reach an agreement"],["proposal","a suggested plan or action"],["position","a party’s view on an issue"],["availability","times when a person is free"],],typing:"If there is an appetite to resolve the matter, please indicate your availability for a settlement call."},
{focus:"Career communication",level:"Advanced",minutes:24,speakTitle:"Talk about your development",speakPrompt:"Your manager asks what skill you want to improve. Explain your goal confidently and specifically.",question:"What communication skill would you like to develop?",instruction:"Name the skill → explain why → describe how you are practicing it.",tip:"Do not minimize yourself with “My English is bad.” Talk about the skill you are building.",examples:[["Simple","I want to improve my workplace communication.","Try this"],["Specific","I want to become more confident when speaking with clients and counsel.","Use this"],["Professional","I’m working on being more concise and confident in workplace conversations.","Use this"],["Action-focused","I’m practicing speaking, client calls and professional email writing every day.","Use this"],["Strong","I’m working on becoming more concise and confident in workplace communication, especially during client calls, discussions with counsel and professional emails. I’m practicing these skills consistently and tracking my progress.","Use this"]],scenario:["Career","Hard","A manager asks what you want to take on more independently.","Speak about your strengths and your development goal without underselling yourself."],choices:["“I’m not sure.”","“I’d like to take on more responsibility and continue developing my communication and file-management skills.”","“Anything is fine.”"],model:"“I’d like to continue taking on more responsibility independently while developing my communication skills, particularly in client calls, counsel communication and professional written correspondence.”",phrases:["I’m working on…","I’d like to develop…","I’m comfortable with…","I’d like to take on more…","One area I’m focusing on is…"],email:["Ask for a development conversation","Write a short message asking for a career-development conversation.","Hi Steven,<br><br>I’d appreciate the opportunity to discuss my development goals and get your feedback on areas where I can continue to grow and take on more responsibility. Please let me know a convenient time to connect.<br><br>Thank you."],edits:[["“I’m not good at speaking.”","“I’m working on becoming more confident when speaking.”"],["“I need help with English.”","“I’m developing my workplace communication skills.”"],["“I want a promotion.”","“I’d like to discuss opportunities to take on more responsibility.”"],["“I can do everything.”","“I’m comfortable managing these tasks independently.”"],["“I think I’m okay.”","“One of my strengths is…”"]],read:["Confidence and career growth","Career communication is not only about grammar. It is also about being able to describe your work clearly, ask for responsibility and explain what you are improving. Use evidence: the work you manage, the problems you solve and the communication skills you are actively building."],vocab:[["independent","able to work without needing constant direction"],["responsibility","a duty or task you are expected to manage"],["development","growth or improvement in a skill"],["strength","an area where you perform well"],["initiative","taking useful action without waiting to be told"],],typing:"I’d like to continue taking on more responsibility while developing my communication skills."}
];

